import { useNavigate } from "react-router-dom";
import { LogOut, Timer } from "lucide-react";
import { toast } from "react-hot-toast";
import { useEffect, useState, useRef } from "react";
import api from "@/utils/api";
import useAuth from "@/hooks/useAuth";
import jwtDecode from "jwt-decode";

export default function NavbarAdmin() {
  const navigate = useNavigate();
  const { user, logout } = useAuth();
  const [remainingTime, setRemainingTime] = useState(null);
  const hasShownWarning = useRef(false);
  const [showExtendButton, setShowExtendButton] = useState(false);

  // 🔁 Suivi de l'expiration de session
  useEffect(() => {
    if (!user?.exp) return;

    const interval = setInterval(() => {
      const now = Date.now() / 1000;
      const timeLeft = user.exp - now;

      if (timeLeft <= 0) {
        logout();
        clearInterval(interval);
      } else {
        if (timeLeft <= 60 && !hasShownWarning.current) {
          toast.error("⚠️ Votre session expire dans moins d’une minute.");
          setShowExtendButton(true);
          hasShownWarning.current = true;
        }

        const hours = Math.floor(timeLeft / 3600);
        const minutes = Math.floor((timeLeft % 3600) / 60);
        const seconds = Math.floor(timeLeft % 60);
        setRemainingTime(`${hours}h ${minutes}m ${seconds}s`);
      }
    }, 1000);

    return () => clearInterval(interval);
  }, [user?.exp, logout]);

  // 🔁 Prolonger la session via /admin/refresh
  const extendSession = async () => {
    try {
      const res = await api.post("/admin/refresh");
      if (res.data?.token) {
        localStorage.setItem("adminToken", res.data.token);
        const decoded = jwtDecode(res.data.token);
        toast.success("✅ Session prolongée !");
        setShowExtendButton(false);
        hasShownWarning.current = false;
        window.location.reload(); // pour forcer la relecture du token
      }
    } catch {
      toast.error("❌ Échec du renouvellement. Veuillez vous reconnecter.");
      logout();
    }
  };

  return (
    <nav className="bg-red-700 text-white px-6 py-4 flex flex-col md:flex-row md:justify-between md:items-center shadow-md">
      <div className="text-lg font-bold mb-2 md:mb-0">
        CDO Tchad – Espace Administration
      </div>

      <div className="flex flex-col sm:flex-row items-start sm:items-center gap-2 sm:gap-4 text-sm">
        {user?.email && (
          <span className="text-white font-medium">
            Connecté en tant que : <span className="underline">{user.email}</span>
          </span>
        )}

        {remainingTime && (
          <span className="flex items-center gap-1 text-white text-xs">
            <Timer className="w-4 h-4" />
            Session expire dans :{" "}
            <span className="font-semibold">{remainingTime}</span>
          </span>
        )}

        {showExtendButton && (
          <button
            onClick={extendSession}
            className="bg-yellow-500 hover:bg-yellow-600 text-white px-3 py-1 rounded text-xs"
          >
            Prolonger la session
          </button>
        )}

        <button
          onClick={logout}
          className="flex items-center gap-2 bg-white text-red-700 font-semibold px-3 py-1 rounded hover:bg-red-100 transition"
        >
          <LogOut className="w-4 h-4" />
          Déconnexion
        </button>
      </div>
    </nav>
  );
}
