// frontend/components/admin/FormulaireOffreCDO.jsx
import { useState, useEffect } from "react";
import { useNavigate, useParams, useSearchParams } from "react-router-dom";
import jsPDF from "jspdf";
import { toast } from "react-toastify";
import { Loader2 } from "lucide-react";
import api from "@/utils/api";

export default function FormulaireOffreCDO() {
  useEffect(() => {
    if (localStorage.getItem("offre_success")) {
      toast.success("✅ Offre enregistrée avec succès");
      localStorage.removeItem("offre_success");
    }
  }, []);
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);
  const [errors, setErrors] = useState({});
  const [extraFile, setExtraFile] = useState(null);
  const [pdfPreviewUrl, setPdfPreviewUrl] = useState(null);
  const [currentStep, setCurrentStep] = useState(0);

  const [searchParams] = useSearchParams();
  const offreId = searchParams.get("offreId");

  const [formData, setFormData] = useState(() => {
    const saved = localStorage.getItem("formulaire_offre_draft");
    return saved
      ? JSON.parse(saved)
      : {
          titre: "",
          resume: "",
          lieu: "",
          employeur: "CDO Consulting Tchad",
          type_contrat: "CDI",
          langue: "Français",
          diplome: "",
          description: "",
          attributions: "",
          competences: "",
          formation: "",
          experience: "",
          certifications: "",
          logiciels: "",
          affiliations: "",
          date_publication: "",
          date_limite: ""
        };
  });

  useEffect(() => {
    localStorage.setItem("formulaire_offre_draft", JSON.stringify(formData));
  }, [formData]);

  const fieldLabels = {
    titre: "Titre de l'offre",
    resume: "Résumé",
    lieu: "Lieu de travail",
    employeur: "Employeur",
    type_contrat: "Type de contrat",
    langue: "Langue requise",
    diplome: "Diplôme requis",
    description: "Description",
    attributions: "Attributions principales",
    competences: "Compétences attendues",
    formation: "Formation exigée",
    experience: "Expérience minimale",
    certifications: "Certifications utiles",
    logiciels: "Compétences logicielles",
    affiliations: "Affiliations ou accréditations",
    date_publication: "Date de publication",
    date_limite: "Date limite"
  };

  useEffect(() => {
    if (offreId) {
      const fetchOffre = async () => {
        try {
          const response = await api.get(`/recrutement/${offreId}`);
          setFormData(response.data);
        } catch (err) {
          console.error("Erreur lors du chargement de l'offre :", err);
        }
      };
      fetchOffre();
    }
  }, [offreId]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
    setErrors((prev) => ({ ...prev, [name]: value.trim() === "" ? "Ce champ est requis." : null }));
  };

  const generatePDFBlob = async () => {
    const doc = new jsPDF();
    let y = 20;
    const margin = 10;
    const pageHeight = doc.internal.pageSize.height;
    const lineHeight = 10;

    const addTextBlock = (label, value) => {
      doc.setFont("helvetica", "bold");
      doc.text(`${label}:`, margin, y);
      y += 6;
      doc.setFont("helvetica", "normal");
      const textLines = doc.splitTextToSize(value || "-", 180);
      textLines.forEach((line) => {
        if (y + lineHeight > pageHeight - margin - 10) {
          doc.addPage();
          y = margin;
        }
        doc.text(line, margin, y);
        y += lineHeight;
      });
      y += 4;
    };

    Object.entries(formData).forEach(([label, val]) => addTextBlock(fieldLabels[label] || label, val));

    const totalPages = doc.internal.getNumberOfPages();
    for (let i = 1; i <= totalPages; i++) {
      doc.setPage(i);
      doc.setFontSize(10);
      doc.text(`Page ${i} / ${totalPages}`, doc.internal.pageSize.width - 40, doc.internal.pageSize.height - 10);
    }

    return doc.output("blob");
  };

  const generatePDF = async () => {
    try {
      const blob = await generatePDFBlob();
      const url = URL.createObjectURL(blob);
      setPdfPreviewUrl(url);
      const link = document.createElement("a");
      link.href = url;
      link.download = "resume-offre.pdf";
      link.click();
      toast.success("PDF généré avec succès");
    } catch (err) {
      toast.error("Erreur lors de la génération du PDF");
    }
  };

  const validateForm = () => {
    const newErrors = {};
    if (!formData.titre || formData.titre.length < 3) newErrors.titre = "Le titre est requis et doit contenir au moins 3 caractères.";
    if (!formData.lieu) newErrors.lieu = "Le lieu est requis.";
    if (!formData.date_publication) newErrors.date_publication = "La date de publication est requise.";
    if (!formData.date_limite) newErrors.date_limite = "La date limite est requise.";
    else if (formData.date_limite < formData.date_publication) newErrors.date_limite = "La date limite ne peut pas être antérieure à la date de publication.";
    if (!formData.description || formData.description.length < 20) newErrors.description = "La description doit contenir au moins 20 caractères.";
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    if (!validateForm()) {
      setLoading(false);
      toast.error("Veuillez corriger les erreurs.");
      return;
    }
    try {
      const pdfBlob = await generatePDFBlob();
      const form = new FormData();
      Object.entries(formData).forEach(([key, value]) => form.append(key, value));
      form.append("document", new File([pdfBlob], "resume-offre.pdf", { type: "application/pdf" }));
      if (extraFile) form.append("fichier_joint", extraFile);
      const res = await api.request({
        url: offreId ? `/recrutement/${offreId}` : "/recrutement",
        method: offreId ? "PUT" : "POST",
        data: form,
        headers: { "Content-Type": "multipart/form-data" }
      });
      localStorage.removeItem("formulaire_offre_draft");
      toast.success("Offre enregistrée avec succès");
      localStorage.setItem("offre_success", "1");
      navigate(0); // 🔄 recharge automatique après succès
    } catch (err) {
      toast.error(err.message || "Erreur réseau");
    } finally {
      setLoading(false);
    }
  };

  const groupedFields = [
    { title: "Informations générales", keys: ["titre", "resume", "lieu", "employeur", "type_contrat", "langue", "diplome"] },
    { title: "Détails du poste", keys: ["description", "attributions", "competences"] },
    { title: "Exigences", keys: ["formation", "experience", "certifications", "logiciels", "affiliations"] },
    { title: "Dates", keys: ["date_publication", "date_limite"] }
  ];

  const progressPercent = Math.round(((currentStep + 1) / groupedFields.length) * 100);

  return (
    <div className="max-w-4xl mx-auto p-6 bg-white rounded shadow">
      <h2 className="text-2xl font-bold mb-4 text-red-700">{offreId ? "Modifier une offre" : "Ajouter une offre"}</h2>

      <div className="w-full bg-gray-200 rounded-full h-2.5 mb-2">
        <div className="bg-red-600 h-2.5 rounded-full transition-all duration-300" style={{ width: `${progressPercent}%` }}></div>
      </div>
      <p className="text-sm text-gray-600 mb-4 text-right">✅ Étape {currentStep + 1} sur {groupedFields.length}</p>

      <div className="flex justify-between items-center mb-6">
        {groupedFields.map((section, index) => (
          <div
            key={section.title}
            className={`flex-1 text-center py-1 border-b-4 font-medium text-sm cursor-pointer ${
              currentStep === index ? "border-red-600 text-red-700" : "border-gray-200 text-gray-500"
            }`}
            onClick={() => setCurrentStep(index)}
          >
            {section.title}
          </div>
        ))}
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        <fieldset className="border p-4 rounded">
          <legend className="font-semibold text-lg text-gray-700 mb-2">{groupedFields[currentStep].title}</legend>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {groupedFields[currentStep].keys.map((key) => (
              <div key={key} className="col-span-1">
                <label className="block font-medium">{fieldLabels[key] || key}</label>
                {key.includes("description") || key.includes("attributions") || key.includes("competences") || key.includes("resume") ? (
                  <textarea name={key} value={formData[key]} onChange={handleChange} className="w-full border p-2 rounded" />
                ) : (
                  <input type={key.includes("date") ? "date" : "text"} name={key} value={formData[key]} onChange={handleChange} className="w-full border p-2 rounded" />
                )}
                {errors[key] && <p className="text-red-600 text-sm mt-1">{errors[key]}</p>}
              </div>
            ))}
          </div>
        </fieldset>

        <div className="flex justify-between">
          <button type="button" disabled={currentStep === 0} onClick={() => setCurrentStep((prev) => prev - 1)} className="px-4 py-2 rounded bg-gray-200">Précédent</button>
          {currentStep < groupedFields.length - 1 ? (
            <button type="button" onClick={() => setCurrentStep((prev) => prev + 1)} className="px-4 py-2 rounded bg-blue-600 text-white">Suivant</button>
          ) : (
            <button type="submit" disabled={loading} className="bg-green-600 text-white px-4 py-2 rounded hover:bg-green-700 flex items-center">
              {loading && <Loader2 className="animate-spin mr-2 h-4 w-4" />}
              {loading ? "Envoi en cours..." : offreId ? "Modifier" : "Envoyer"}
            </button>
          )}
        </div>

        <div className="border p-4 rounded">
          <label className="block font-medium">Fichier joint (facultatif)</label>
          <input type="file" accept=".pdf,.doc,.docx" onChange={(e) => setExtraFile(e.target.files[0])} className="w-full border p-2 rounded" />
        </div>

        <button type="button" onClick={generatePDF} className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700">Télécharger PDF</button>

        <div className="mt-4">
          <h4 className="font-semibold text-sm mb-2">Aperçu du PDF :</h4>
          {pdfPreviewUrl ? (
            <iframe src={pdfPreviewUrl} className="w-full h-72 border rounded" title="Aperçu PDF" />
          ) : (
            <p className="text-gray-500 text-sm italic">Aucun PDF généré pour l'instant.</p>
          )}
        </div>
      </form>
    </div>
  );
}
