import { useEffect, useState } from "react";
import api from "@/utils/api";
import { BarChart2, FileDown, FileText } from "lucide-react";
import html2canvas from "html2canvas";
import jsPDF from "jspdf";

export default function ActualiteStatsCard() {
  const [stats, setStats] = useState([]);

  useEffect(() => {
    const fetchStats = async () => {
      try {
        const res = await api.get("/actualites/stats");
        setStats(res.data);
      } catch (err) {
        console.error("Erreur récupération stats actualités", err);
      }
    };
    fetchStats();
  }, []);

  const exportPDF = async () => {
    const element = document.getElementById("actualite-stats");
    const canvas = await html2canvas(element);
    const imgData = canvas.toDataURL("image/png");
    const pdf = new jsPDF("p", "mm", "a4");
    const width = pdf.internal.pageSize.getWidth();
    const height = (canvas.height * width) / canvas.width;
    pdf.addImage(imgData, "PNG", 0, 10, width, height);
    pdf.save("stats-actualites.pdf");
  };

  const exportCSV = () => {
    const csvRows = [
      ["Catégorie", "Total"],
      ...stats.map((item) => [item.categorie, item.total]),
    ];
    const csvContent = csvRows.map((e) => e.join(",")).join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.setAttribute("download", "stats-actualites.csv");
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="bg-white p-4 mt-6 rounded-xl shadow border" id="actualite-stats">
      <div className="flex justify-between items-center mb-4">
        <h2 className="text-lg font-bold flex items-center gap-2">
          <BarChart2 className="text-indigo-500" />
          Statistiques des actualités par catégorie
        </h2>
        <div className="flex gap-2">
          <button
            onClick={exportPDF}
            className="bg-red-600 hover:bg-red-700 text-white px-3 py-1 rounded text-sm flex items-center gap-1"
          >
            <FileText size={16} />
            PDF
          </button>
          <button
            onClick={exportCSV}
            className="bg-green-600 hover:bg-green-700 text-white px-3 py-1 rounded text-sm flex items-center gap-1"
          >
            <FileDown size={16} />
            CSV
          </button>
        </div>
      </div>

      {stats.length === 0 ? (
        <p className="text-gray-500">Aucune donnée disponible.</p>
      ) : (
        <ul className="space-y-2">
          {stats.map((item, index) => (
            <li key={index} className="flex justify-between">
              <span className="capitalize">{item.categorie}</span>
              <span className="font-semibold">{item.total}</span>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}
