// 📁 src/context/AuthContext.jsx
import { createContext, useContext, useEffect, useState, useRef } from "react";
import { useLocation } from "react-router-dom";
import jwtDecode from "jwt-decode";
import toast from "react-hot-toast";

const AuthContext = createContext();

export const AuthProvider = ({ children }) => {
  const [admin, setAdmin] = useState(null);
  const [initialCheckDone, setInitialCheckDone] = useState(false);
  const [isLoggingIn, setIsLoggingIn] = useState(false); // ✅ nouvelle protection
  const hasShownToast = useRef(false);
  const location = useLocation();

  useEffect(() => {
    if (isLoggingIn) return; // ⛔️ ne rien faire pendant le login

    const storedUser = localStorage.getItem("adminUser") || sessionStorage.getItem("adminUser");
    const storedToken = localStorage.getItem("adminToken") || sessionStorage.getItem("adminToken");

    if (!storedToken || !storedUser) {
      setInitialCheckDone(true);
      return;
    }

    try {
      const decoded = jwtDecode(storedToken);
      const now = Date.now() / 1000;

      if (decoded.exp && decoded.exp > now) {
        try {
          const parsedUser = JSON.parse(storedUser);
          setAdmin(parsedUser);
        } catch (e) {
          console.error("❌ adminUser mal formaté :", storedUser);
        }
      } else {
        if (!hasShownToast.current) {
          hasShownToast.current = true;
          toast.error("Session expirée. Veuillez vous reconnecter.");
        }
        logout();
      }
    } catch (error) {
      console.error("❌ Token invalide :", error);
      if (!hasShownToast.current) {
        hasShownToast.current = true;
        toast.error("Token invalide. Veuillez vous reconnecter.");
      }
      logout();
    } finally {
      setInitialCheckDone(true);
    }
  }, [isLoggingIn, location.pathname]);

  // ✅ Connexion : on bloque temporairement les vérifications
  const login = (token, user, rememberMe = true) => {
    if (!token || !user) return;
    setIsLoggingIn(true); // ✅ bloque le useEffect
    const storage = rememberMe ? localStorage : sessionStorage;
    storage.setItem("adminToken", token);
    storage.setItem("adminUser", JSON.stringify(user));
    setAdmin(user);
    setTimeout(() => setIsLoggingIn(false), 500); // ⏳ délai pour propagation
  };

  // 🔓 Déconnexion
  const logout = () => {
    localStorage.removeItem("adminToken");
    localStorage.removeItem("adminUser");
    sessionStorage.removeItem("adminToken");
    sessionStorage.removeItem("adminUser");
    setAdmin(null);
  };

  return (
    <AuthContext.Provider value={{ admin, login, logout, initialCheckDone }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => useContext(AuthContext);
