// 📁 src/utils/adminApi.js
import api from "./api";

// ✅ ADMIN - Utilisateurs

export const fetchUtilisateurs = async () => {
  const response = await api.get("/utilisateurs");
  return response.data;
};

export const ajouterUtilisateur = async (data) => {
  const response = await api.post(`/utilisateurs`, data);
  return response.data;
};

export const supprimerUtilisateur = async (id) => {
  const response = await api.delete(`/utilisateurs/${id}`);
  return response.data;
};

export const updateUtilisateur = async (id, data) => {
  const response = await api.put(`/utilisateurs/${id}`, data);
  return response.data;
};


