// ✅ Créer ou modifier une actualité selon la présence d’un ID
export const saveActualite = async (formData, id = null) => {
  const response = id
    ? await api.put(`/actualites/${id}`, formData)
    : await api.post("/actualites", formData);
  return response.data;
};

